use color_port::{format_float, ColorConverter, RGB};

fn main() {
    let mut colors = vec![
        RGB::new(0.1_f32, 0.2_f32, 0.3_f32),
        RGB::new(0.4_f32, 0.5_f32, 0.6_f32),
        RGB::new(0.7_f32, 0.2_f32, 0.1_f32),
        RGB::new(0.3_f32, 0.8_f32, 0.4_f32),
        RGB::new(0.9_f32, 0.1_f32, 0.8_f32),
    ];

    let args: Vec<String> = std::env::args().collect();
    let mut index = 1_usize;
    while index + 2 < args.len() {
        let r: f32 = args[index].parse().unwrap();
        let g: f32 = args[index + 1].parse().unwrap();
        let b: f32 = args[index + 2].parse().unwrap();
        colors.push(RGB::new(r, g, b));
        index += 3;
    }

    let mut output = String::new();

    for (i, rgb) in colors.iter().copied().enumerate() {
        let hsl = ColorConverter::rgb_to_hsl(rgb);
        let hsv = ColorConverter::rgb_to_hsv(rgb);
        let cmyk = ColorConverter::rgb_to_cmyk(rgb);
        let yuv = ColorConverter::rgb_to_yuv(rgb);
        let bright = ColorConverter::adjust_brightness(rgb, 1.2_f32);
        let dark = ColorConverter::adjust_brightness(rgb, 0.8_f32);
        let saturated = ColorConverter::adjust_saturation(rgb, 1.5_f32);
        let gray = ColorConverter::grayscale(rgb);
        let inverted = ColorConverter::invert(rgb);

        let mut line = String::new();
        line.push_str("Color ");
        line.push_str(&i.to_string());
        line.push_str(": ");

        push_rgb(&mut line, rgb);
        push_hsl(&mut line, hsl);
        push_hsv(&mut line, hsv);
        push_cmyk(&mut line, cmyk);
        push_yuv(&mut line, yuv);
        push_rgb(&mut line, bright);
        push_rgb(&mut line, dark);
        push_rgb(&mut line, saturated);
        push_rgb(&mut line, gray);
        push_rgb(&mut line, inverted);

        if i + 1 == colors.len() && colors.len() > 1 {
            push_float(&mut line, ColorConverter::color_distance(rgb, colors[0]));
        }

        output.push_str(&line);
        output.push('\n');
    }

    print!("{output}");
}

fn push_rgb(line: &mut String, rgb: RGB) {
    push_float(line, rgb.r);
    push_float(line, rgb.g);
    push_float(line, rgb.b);
}

fn push_hsl(line: &mut String, hsl: color_port::HSL) {
    push_float(line, hsl.h);
    push_float(line, hsl.s);
    push_float(line, hsl.l);
}

fn push_hsv(line: &mut String, hsv: color_port::HSV) {
    push_float(line, hsv.h);
    push_float(line, hsv.s);
    push_float(line, hsv.v);
}

fn push_cmyk(line: &mut String, cmyk: color_port::CMYK) {
    push_float(line, cmyk.c);
    push_float(line, cmyk.m);
    push_float(line, cmyk.y);
    push_float(line, cmyk.k);
}

fn push_yuv(line: &mut String, yuv: color_port::YUV) {
    push_float(line, yuv.y);
    push_float(line, yuv.u);
    push_float(line, yuv.v);
}

fn push_float(line: &mut String, value: f32) {
    line.push_str(&format_float(value));
    line.push(' ');
}

