const PRECISION: usize = 6;

pub fn format_float(value: f32) -> String {
    let value64 = value as f64;

    if value64.is_nan() {
        return "nan".to_string();
    }
    if value64.is_infinite() {
        return if value64.is_sign_negative() {
            "-inf".to_string()
        } else {
            "inf".to_string()
        };
    }

    let scientific = format!("{:.*e}", PRECISION - 1, value64);
    let (mantissa, exponent) = scientific
        .split_once('e')
        .expect("scientific format must contain an exponent");
    let exponent: i32 = exponent.parse().expect("valid exponent");

    if exponent < -4 || exponent >= PRECISION as i32 {
        let mantissa = trim_fractional_zeros(mantissa);
        let sign = if exponent < 0 { '-' } else { '+' };
        let magnitude = exponent.abs();
        return format!("{mantissa}e{sign}{magnitude:02}");
    }

    let decimals = (PRECISION as i32 - (exponent + 1)).max(0) as usize;
    let fixed = format!("{:.*}", decimals, value64);
    trim_fractional_zeros(&fixed)
}

fn trim_fractional_zeros(input: &str) -> String {
    if !input.contains('.') {
        return input.to_string();
    }

    let mut trimmed = input.to_string();
    while trimmed.ends_with('0') {
        trimmed.pop();
    }
    if trimmed.ends_with('.') {
        trimmed.pop();
    }
    trimmed
}

