use crate::models::{CMYK, HSL, HSV, RGB, YUV};

pub struct ColorConverter;

impl ColorConverter {
    pub fn rgb_to_hsl(rgb: RGB) -> HSL {
        let max = rgb.r.max(rgb.g).max(rgb.b);
        let min = rgb.r.min(rgb.g).min(rgb.b);
        let l = (max + min) / 2.0_f32;

        if max == min {
            return HSL {
                h: 0.0_f32,
                s: 0.0_f32,
                l,
            };
        }

        let delta = max - min;
        let s = if l > 0.5_f32 {
            delta / (2.0_f32 - max - min)
        } else {
            delta / (max + min)
        };

        let mut h = if max == rgb.r {
            (rgb.g - rgb.b) / delta + if rgb.g < rgb.b { 6.0_f32 } else { 0.0_f32 }
        } else if max == rgb.g {
            (rgb.b - rgb.r) / delta + 2.0_f32
        } else {
            (rgb.r - rgb.g) / delta + 4.0_f32
        };

        h *= 60.0_f32;

        HSL { h, s, l }
    }

    pub fn rgb_to_hsv(rgb: RGB) -> HSV {
        let max = rgb.r.max(rgb.g).max(rgb.b);
        let min = rgb.r.min(rgb.g).min(rgb.b);
        let delta = max - min;

        let v = max;
        if delta == 0.0_f32 || max == 0.0_f32 {
            return HSV {
                h: 0.0_f32,
                s: 0.0_f32,
                v,
            };
        }

        let s = delta / max;

        let mut h = if max == rgb.r {
            (rgb.g - rgb.b) / delta
        } else if max == rgb.g {
            (rgb.b - rgb.r) / delta + 2.0_f32
        } else {
            (rgb.r - rgb.g) / delta + 4.0_f32
        };

        h *= 60.0_f32;
        if h < 0.0_f32 {
            h += 360.0_f32;
        }

        HSV { h, s, v }
    }

    pub fn rgb_to_cmyk(rgb: RGB) -> CMYK {
        let k = 1.0_f32 - rgb.r.max(rgb.g).max(rgb.b);

        if k == 1.0_f32 {
            return CMYK {
                c: 0.0_f32,
                m: 0.0_f32,
                y: 0.0_f32,
                k,
            };
        }

        let scale = 1.0_f32 - k;

        CMYK {
            c: (1.0_f32 - rgb.r - k) / scale,
            m: (1.0_f32 - rgb.g - k) / scale,
            y: (1.0_f32 - rgb.b - k) / scale,
            k,
        }
    }

    pub fn rgb_to_yuv(rgb: RGB) -> YUV {
        YUV {
            y: 0.299_f32 * rgb.r + 0.587_f32 * rgb.g + 0.114_f32 * rgb.b,
            u: -0.147_f32 * rgb.r - 0.289_f32 * rgb.g + 0.436_f32 * rgb.b,
            v: 0.615_f32 * rgb.r - 0.515_f32 * rgb.g - 0.100_f32 * rgb.b,
        }
    }

    pub fn adjust_brightness(rgb: RGB, factor: f32) -> RGB {
        RGB {
            r: clamp01(rgb.r * factor),
            g: clamp01(rgb.g * factor),
            b: clamp01(rgb.b * factor),
        }
    }

    pub fn adjust_saturation(rgb: RGB, factor: f32) -> RGB {
        let mut hsl = Self::rgb_to_hsl(rgb);
        hsl.s = clamp01(hsl.s * factor);
        hsl_to_rgb(hsl)
    }

    pub fn grayscale(rgb: RGB) -> RGB {
        let gray = 0.2126_f32 * rgb.r + 0.7152_f32 * rgb.g + 0.0722_f32 * rgb.b;
        RGB {
            r: gray,
            g: gray,
            b: gray,
        }
    }

    pub fn invert(rgb: RGB) -> RGB {
        RGB {
            r: 1.0_f32 - rgb.r,
            g: 1.0_f32 - rgb.g,
            b: 1.0_f32 - rgb.b,
        }
    }

    pub fn color_distance(a: RGB, b: RGB) -> f32 {
        let dr = a.r - b.r;
        let dg = a.g - b.g;
        let db = a.b - b.b;
        (dr * dr + dg * dg + db * db).sqrt()
    }
}

fn clamp01(value: f32) -> f32 {
    value.clamp(0.0_f32, 1.0_f32)
}

fn hsl_to_rgb(hsl: HSL) -> RGB {
    if hsl.s == 0.0_f32 {
        return RGB {
            r: hsl.l,
            g: hsl.l,
            b: hsl.l,
        };
    }

    let hue = hsl.h / 360.0_f32;
    let q = if hsl.l < 0.5_f32 {
        hsl.l * (1.0_f32 + hsl.s)
    } else {
        hsl.l + hsl.s - hsl.l * hsl.s
    };
    let p = 2.0_f32 * hsl.l - q;

    RGB {
        r: hue_to_rgb(p, q, hue + 1.0_f32 / 3.0_f32),
        g: hue_to_rgb(p, q, hue),
        b: hue_to_rgb(p, q, hue - 1.0_f32 / 3.0_f32),
    }
}

fn hue_to_rgb(p: f32, q: f32, mut t: f32) -> f32 {
    if t < 0.0_f32 {
        t += 1.0_f32;
    }
    if t > 1.0_f32 {
        t -= 1.0_f32;
    }
    if t < 1.0_f32 / 6.0_f32 {
        return p + (q - p) * 6.0_f32 * t;
    }
    if t < 1.0_f32 / 2.0_f32 {
        return q;
    }
    if t < 2.0_f32 / 3.0_f32 {
        return p + (q - p) * (2.0_f32 / 3.0_f32 - t) * 6.0_f32;
    }
    p
}
